mapper.insert:
INSERT INTO ${table} (revision_id, file_id, ${columns})
SELECT n.revision_id, n.file_id, ${sourceColumns}
  FROM analysis_file n
  JOIN analysis_file_pass p ON p.file_id = n.file_id AND p.pass = #{pass} AND p.carried
  JOIN ${table} t ON t.file_id = n.carried_from_file_id
 WHERE n.revision_id = #{revisionId}
   AND n.carried_from_file_id IS NOT NULL

   AND t.relation_type NOT IN
    #{type}
